    );
    if (error) {
      throw new Error(`LookProfile konnte nicht archiviert werden: ${error.message}`);
    }
    const record = await this.loadRecord(id);
    if (!record) {
      throw new Error('LookProfile nach Archivierung nicht lesbar.');
    }
    return record;
  }

