    );
    if (error) {
      throw new Error(`Look-Versionen konnten nicht geladen werden: ${error.message}`);
    }
    return ((data ?? []) as LookProfileVersionDto[])
      .map(mapLookProfileVersionRow)
      .filter((row): row is LookProfileVersion => row !== null);
  }

